class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long c2(long x) {
    return x * (x - 1) / 2;
  }

  public int subsequencesWithMiddleMode(int[] nums) {
    int n = nums.length;
    int[] sorted = nums.clone();
    java.util.Arrays.sort(sorted);
    int m = 0;
    for (int i = 0; i < n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
    int[] id = new int[n];
    int[] cl = new int[m], cr = new int[m];
    for (int i = 0; i < n; i++) {
      id[i] = java.util.Arrays.binarySearch(sorted, 0, m, nums[i]);
      cr[id[i]]++;
    }
    long ans = 0;
    for (int i = 0; i < n; i++) {
      int v = id[i];
      cr[v]--;
      int L = i, R = n - 1 - i;
      long a = cl[v], b = cr[v];
      long lo = L - a, ro = R - b;
      long sum = c2(a) % MOD * (c2(b) % MOD) % MOD;
      sum += c2(a) % MOD * (b * ro % MOD) % MOD;
      sum += a * lo % MOD * (c2(b) % MOD) % MOD;
      sum += c2(a) % MOD * (c2(ro) % MOD) % MOD;
      sum += c2(lo) % MOD * (c2(b) % MOD) % MOD;
      sum += a * lo % MOD * (b * ro % MOD) % MOD;
      long sl = 0, sr = 0;
      for (int w = 0; w < m; w++) {
        if (w == v) continue;
        sl += c2(cl[w]);
        sr += c2(cr[w]);
      }
      long t1 = 0, t2 = 0;
      for (int u = 0; u < m; u++) {
        if (u == v) continue;
        if (cl[u] > 0) {
          long np = ro - cr[u];
          long d = c2(np) - (sr - c2(cr[u]));
          t1 = (t1 + cl[u] * (d % MOD)) % MOD;
        }
        if (cr[u] > 0) {
          long np = lo - cl[u];
          long d = c2(np) - (sl - c2(cl[u]));
          t2 = (t2 + cr[u] * (d % MOD)) % MOD;
        }
      }
      sum += a % MOD * t1 % MOD + b % MOD * t2 % MOD;
      ans = (ans + sum) % MOD;
      cl[v]++;
    }
    return (int) ans;
  }
}
